create table if not exists public.franchise_owner_assignments (id bigint generated by default as identity primary key,user_id uuid not null unique references auth.users(id) on delete cascade,franchise_slug text not null unique,franchise_name text not null,owner_name text not null,is_active boolean not null default true,created_at timestamptz not null default now());
alter table public.franchise_owner_assignments enable row level security;
drop policy if exists "Owners read own assignment" on public.franchise_owner_assignments;create policy "Owners read own assignment" on public.franchise_owner_assignments for select to authenticated using(user_id=auth.uid());
create or replace view public.owner_visible_players with(security_invoker=true) as select id,full_name,district,primary_role,batting_style,bowling_style,cricheroes_url,created_at,coalesce(franchise_slug,'') franchise_slug from public.players where lower(coalesce(status,'')) in ('verified','approved','draft_eligible','drafted','selected');grant select on public.owner_visible_players to authenticated;
-- Replace each placeholder email with the exact Supabase Authentication email, then run the matching insert.
